export const garmentNames={tee:'Remera',hoodie:'Hoodie',pants:'Pantalón',shorts:'Bermuda',blank:'En blanco'};
function sleeve(left,hoodie=false){const d=hoodie?'M 251 211 C 226 210 205 220 190 251 L 127 401 Q 125 414 141 420 L 177 435 Q 190 438 197 419 L 245 309 Q 257 279 259 257':'M 247 212 C 227 214 210 219 195 229 Q 184 235 179 250 L 149 308 L 211 338 C 225 313 239 288 251 267';const o=P(left?'Manga izquierda':'Manga derecha',d+' Z','#fff');o.category='structure';o.structureKey=left?'Manga izquierda':'Manga derecha';if(!left)o.matrix=[-1,0,0,1,700,0];return o;}
function tee(back){const body=P('Cuerpo','M 247 212 L 300 191 Q 350 210 400 191 L 453 212 C 450 300 456 391 460 480 Q 350 486 240 480 C 244 391 250 300 247 212 Z','#fff',{role:'body',category:'structure',structureKey:'Cuerpo'});const collar=P('Cuello',back?'M 300 191 Q 350 205 400 191 L 405 201 Q 350 222 295 201 Z':'M 300 191 C 307 237 393 237 400 191 L 409 198 C 399 251 301 251 291 198 Z','#fff');const hem=P('Dobladillo','M 242 468 Q 350 474 458 468','none',{semanticType:'hemGuide'});collar.category='structure';collar.structureKey='Cuello';const a=P('Costura manga izquierda','M 157 294 L 218 324');const b=P('Costura manga derecha','M 543 294 L 482 324');return [sleeve(true),sleeve(false),body,collar,hem,a,b,linked(hem,'stitch',{offset:5}),linked(a,'stitch',{offset:4}),linked(b,'stitch',{offset:-4})];}
function hoodie(back){const body=P('Cuerpo','M 251 211 L 303 190 Q 350 213 397 190 L 449 211 C 451 303 460 388 462 454 Q 350 462 238 454 C 240 388 249 303 251 211 Z','#fff',{role:'body',category:'structure',structureKey:'Cuerpo'});const band=P('Cintura rib','M 238 454 Q 350 462 462 454 L 458 488 Q 350 496 242 488 Z','#fff');const cuff=P('Puño izquierdo','M 132 409 L 183 430 L 171 458 L 121 437 Z','#fff');const cuff2=P('Puño derecho','M 568 409 L 517 430 L 529 458 L 579 437 Z','#fff');const hood=P('Capucha',back?'M 294 197 C 270 179 274 120 292 107 C 321 83 377 83 406 107 C 427 125 430 179 403 197 Q 350 222 294 197 Z':'M 303 209 C 279 193 274 147 294 117 C 319 81 381 81 406 117 C 426 147 421 193 397 209 Q 350 225 303 209 Z','#fff');const interior=P(back?'Costura capucha':'Abertura capucha',back?'M 350 98 C 342 125 345 164 350 210':'M 350 100 C 321 129 294 174 313 204 Q 350 220 387 204 C 406 174 379 129 350 100 Z',back?'none':'#f5f5f2');const seam=P('Costura lateral izquierda','M 257 278 Q 246 365 244 448');const seam2=P('Costura lateral derecha','M 443 278 Q 454 365 456 448');for(const o of [cuff,cuff2,band,hood]){o.category='structure';o.structureKey=o.name;}let list=[sleeve(true,true),sleeve(false,true),body,cuff,cuff2,band,hood,interior,seam,seam2];band.modifiers=[modifier('rib',{spacing:7,inset:2})];cuff.modifiers=[modifier('rib',{spacing:5})];cuff2.modifiers=[modifier('rib',{spacing:5})];if(!back){list.push(...resource('kangaroo',true).map(o=>{o.matrix=translate(276,342);return o;}));list.push(...resource('cordFlat',true).map(o=>{o.matrix=translate(319,208);return o;}));list.push(...resource('cordFlat',true).map(o=>{o.matrix=translate(379,208);return o;}));}return list;}
function pants(back,short){const bottom=short?461:602;const y=short?441:582;const body=P('Cuerpo',`M 232 146 Q 350 136 468 146 C 475 180 479 219 478 255 C 480 300 487 ${bottom-50} 491 ${bottom} L 369 ${bottom} C 366 ${bottom-80} 358 339 355 322 Q 350 314 345 322 C 342 339 334 ${bottom-80} 331 ${bottom} L 209 ${bottom} C 213 ${bottom-50} 220 300 222 255 C 221 219 225 180 232 146 Z`,'#fff',{role:'body',category:'structure',structureKey:'Cuerpo'});const waist=P('Cintura','M 232 146 Q 350 136 468 146 L 474 180 Q 350 170 226 180 Z','#fff');waist.category='structure';waist.structureKey='Cintura';const crotch=P('Tiro',back?'M 350 176 C 350 224 350 272 350 318':'M 350 176 L 350 317');const hems=[P('Dobladillo izquierdo',`M 212 ${y} L 332 ${y}`,'none',{semanticType:'hemGuide',edgeSide:1}),P('Dobladillo derecho',`M 368 ${y} L 488 ${y}`,'none',{semanticType:'hemGuide',edgeSide:0})];const pockets=back?[...resource('backPocket',true).map(o=>{o.matrix=translate(262,214);return o;}),...resource('backPocket',true).map(o=>{o.matrix=translate(364,214);return o;})]:[P('Bolsillo delantero izquierdo','M 228 181 C 246 210 278 234 310 238'),P('Bolsillo delantero derecho','M 472 181 C 454 210 422 234 390 238'),P('Bragueta','M 365 181 L 365 274 Q 365 292 351 294')];const loops=[];for(const x of [253,322,372,441])loops.push(P('Presilla',`M ${x} 144 L ${x+6} 144 L ${x+6} 186 L ${x} 186 Z`,'#fff',{width:1.2}));return [body,waist,crotch,...pockets,...hems,...loops,...hems.map(o=>linked(o,'stitch',{offset:-5})),...(!back?[P('Botón','M 346 158 C 346 153 354 153 354 158 C 354 163 346 163 346 158 Z','#ddd')]:[])];}
export function newProject(kind){const p=migrateModel(setupTemplateSymmetry({format:'atelier-flat-v1',id:uid(),name:garmentNames[kind]+' — Diseño 01',kind,updated:Date.now(),views:{front:kind==='blank'?[]:kind==='tee'?tee(false):kind==='hoodie'?hoodie(false):pants(false,kind==='shorts'),back:kind==='blank'?[]:kind==='tee'?tee(true):kind==='hoodie'?hoodie(true):pants(true,kind==='shorts')}}));for(const os of Object.values(p.views))for(const o of os){const meta=templateEdges[kind]?.[o.structureKey||o.name];if(meta&&o.nodes)semanticEdges(o,meta.edges);o.width=1.5;if(o.component)o.semanticType=o.component.kind;else if(o.category==='structure')o.semanticType=o.role||'structure';}for(const os of Object.values(p.views))for(const o of os.filter(o=>o.closed&&o.category==='structure'))o.garmentSurface={boundaryIds:[o.id],role:o.role||o.structureKey};bindTemplateGeometry(p);delete p.garment.shared;return migrateModel(p);}
export const resources=[['construction','stitch','Costura simple'],['construction','double','Costura doble'],['construction','seam','Línea de costura'],['construction','panel','Línea de panel'],['hardware','jacketZip','Cierre de campera'],['hardware','jeansZip','Cierre de jean'],['hardware','button','Botón'],['hardware','snap','Broche'],['hardware','eyelet','Ojal metálico'],['details','kangaroo','Bolsillo canguro'],['details','frontPocket','Bolsillo jean'],['details','backPocket','Bolsillo trasero'],['details','cargo','Bolsillo cargo'],['details','sidePocket','Bolsillo lateral'],['details','cuff','Puño rib'],['details','waistband','Cintura rib'],['details','hood','Capucha'],['details','cordThin','Cordón fino'],['details','cordWide','Cordón ancho'],['details','cordFlat','Cordón plano'],['effects','rip','Rasgadura'],['effects','distressed','Corte desgastado'],['effects','raw','Borde crudo'],['construction','elastic','Elástico'],['construction','piping','Vivo / piping'],['construction','binding','Bies'],['hardware','buttons','Fila de botones'],['hardware','eyelets','Fila de ojales']];
function legacyResource(kind,noGroup=false){let os=[];const p=(name,d,fill='none',extra={})=>{const o=P(name,d,fill,extra);os.push(o);return o;};const circle=(r,x=0,y=0)=>`M ${x-r} ${y} C ${x-r} ${y-r*1.333} ${x+r} ${y-r*1.333} ${x+r} ${y} C ${x+r} ${y+r*1.333} ${x-r} ${y+r*1.333} ${x-r} ${y} Z`;
if(kind==='kangaroo'){const o=p('Bolsillo canguro','M 24 0 L 124 0 Q 130 24 148 36 L 148 77 Q 74 83 0 77 L 0 36 Q 18 24 24 0 Z','#fff');os.push(linked(o,'stitch',{offset:4}));}
else if(kind==='backPocket'){const o=p('Bolsillo trasero','M 0 0 L 73 0 L 69 65 L 36 81 L 4 65 Z','#fff');os.push(linked(o,'stitch',{offset:4,rows:2}));p('Dibujo bolsillo','M 8 20 Q 36 41 65 20');}
else if(kind==='cargo'){const o=p('Bolsillo cargo','M 0 0 L 86 0 L 86 99 Q 43 105 0 99 Z','#fff');os.push(linked(o,'stitch',{offset:4}));p('Pliegue','M 37 24 L 37 96', 'none');p('Solapa','M -3 0 L 89 0 L 86 25 L 43 33 L 0 25 Z','#fff');p('Broche izquierdo',circle(2.8,16,16),'#555');p('Broche derecho',circle(2.8,70,16),'#555');}
else if(kind==='frontPocket')p('Bolsillo jean','M 0 0 C 5 37 45 63 76 62 L 78 100 L 0 100 Z','#fff');
else if(kind==='sidePocket')p('Bolsillo lateral','M 0 0 C 8 25 8 59 0 85');
else if(kind==='cuff'||kind==='waistband'){const w=kind==='cuff'?70:220;const o=p('Rib','M 0 0 L '+w+' 0 L '+w+' 35 L 0 35 Z','#fff');o.modifiers=[modifier('rib')];}
else if(kind==='hood'){p('Capucha','M 0 99 C -29 55 -6 0 44 -3 C 100 -5 123 55 91 99 Q 45 114 0 99 Z','#fff');p('Abertura','M 45 0 C 19 29 2 58 12 92 Q 45 102 78 92 C 89 58 72 29 45 0 Z','#f5f5f2');}
else if(kind.startsWith('cord')){const w=kind==='cordThin'?2:kind==='cordWide'?8:5;const o=p('Guía de cordón','M 0 0 C -5 25 6 49 1 73 C -2 85 -9 88 -4 101','none',{hidden:true});os.push(linked(o,'cord',{cordWidth:w,cordStyle:kind==='cordFlat'?'flat':kind==='cordWide'?'wide':'round',stroke:'#656d68'}));}
else if(kind==='button'||kind==='snap'||kind==='eyelet'){p('Herraje',circle(9),'#e9eae7');p('Anillo',circle(6),'none',{width:.8});if(kind==='button')for(const [x,y]of[[-2,-2],[2,-2],[-2,2],[2,2]])p('Perforación',circle(1,x,y),'#444',{width:.4});else p('Centro',circle(kind==='eyelet'?4:2),'#fff');}
else if(kind==='jacketZip'||kind==='jeansZip'){const o=p('Guía de cierre',`M 0 0 L 0 ${kind==='jacketZip'?190:90}`,'none',{hidden:true});os.push(linked(o,'zipper',{zipWidth:kind==='jacketZip'?9:6,teeth:3,teethSpacing:3,zipType:kind==='jacketZip'?'jacket':'jeans',offset:0}));}
else if(kind==='stitch'||kind==='double'){const o=p('Guía de costura','M 0 0 C 30 10 67 -10 100 0','none',{hidden:true});os.push(linked(o,'stitch',{rows:kind==='double'?2:1,offset:0}));}
else if(['elastic','piping','binding','buttons','eyelets'].includes(kind)){const o=p('Guía '+kind,'M 0 0 L 0 140','none',{hidden:true});os.push(linked(o,kind));}
else if(kind==='seam'||kind==='panel')p(kind==='panel'?'Panel':'Línea de costura','M 0 0 C 15 30 -15 70 0 100');
else if(kind==='rip'||kind==='distressed'){p('Rasgadura','M 0 10 L 12 6 L 22 10 L 38 3 L 49 7 L 68 1 L 90 6 L 80 11 L 67 10 L 53 15 L 36 11 L 19 17 Z','#fff',{width:1});for(let x=8;x<86;x+=7)p('Fibra',`M ${x} 6 L ${x+5} 14`,'none',{width:.6});if(kind==='distressed')for(let x=5;x<80;x+=11)p('Desgaste',`M ${x} 0 L ${x+7} -4`,'none',{width:.8});}
else if(kind==='raw')p('Borde crudo','M 0 0 L 6 3 L 12 -2 L 18 2 L 26 -1 L 33 4 L 41 0 L 49 3 L 57 -2 L 65 1 L 75 -1 L 84 3 L 92 0');
const g=uid();if(!noGroup)os.forEach(o=>o.group=g);return os;}

resources.push(...streetResources,...collarResources);for(const r of resources){if(r[0]==='details'){if(r[1].startsWith('cord'))r[0]='cords';else if(r[1]==='hood')r[0]='hoods';else if(/Pocket|cargo|kangaroo/.test(r[1]))r[0]='pockets';}if(r[0]==='effects')r[0]='fabric';}
export function resource(kind,noGroup=false){const collar=collarResource(kind);if(collar)return collar;const smart=smartResource(kind);if(smart)return smart;const os=legacyResource(kind,noGroup);for(const o of os){o.category??=o.source?'construction':o.closed?'detail':'construction';o.semanticType??=o.type;}return os;}

// Keep historical resource commands for saved templates, omit redundant/weak legacy cards.
for(const r of resources)if(['frontPocket','backPocket','cargo','sidePocket','hood','rip','distressed'].includes(r[1]))r[3]='legacy';
